package com.sacco.mvp.lending.controls.controller;

import com.sacco.mvp.lending.controls.dto.CreditControlDtos.*;
import com.sacco.mvp.lending.controls.service.CreditControlService;
import com.sacco.mvp.security.AppUserPrincipal;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.WebDataBinder;
import org.springframework.web.bind.annotation.*;
import java.util.*;

@Controller @RequiredArgsConstructor @RequestMapping("/finance/credit")
public class CreditControlController {
    private final CreditControlService service;
    @GetMapping("/choices/officers") @ResponseBody public List<Choice> officerChoices(@AuthenticationPrincipal AppUserPrincipal a,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page){return service.officerChoices(a,search,page);}
    @GetMapping("/choices/loans/{feature}") @ResponseBody public List<Choice> loanChoices(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable String feature,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page){return service.loanChoices(a,feature,search,page);}
    @InitBinder("policyForm") void policyBinder(WebDataBinder b){b.setAllowedFields("requestKey","expectedRevision","capacityRequired","collateralRequired","verified","reference","remindersEnabled","reminderDaysBefore","reminderEveryDays");}
    @InitBinder("assessmentForm") void assessmentBinder(WebDataBinder b){b.setAllowedFields("requestKey","income","expenses","otherDebt","capacity","assessedOn","validThrough","evidence","policyReference","verified");}
    @InitBinder("assetForm") void assetBinder(WebDataBinder b){b.setAllowedFields("requestKey","code","description","owner","ownerEvidence","verified");}
    @InitBinder("collateralForm") void collateralBinder(WebDataBinder b){b.setAllowedFields("requestKey","expectedSequence","kind","loanId","amount","encumbrance","effectiveDate","validThrough","evidence","reason","verified");}
    @InitBinder("caseForm") void caseBinder(WebDataBinder b){b.setAllowedFields("requestKey","loanId","assignedTo","nextAction","reason");}
    @InitBinder("collectionForm") void collectionBinder(WebDataBinder b){b.setAllowedFields("requestKey","expectedSequence","kind","assignedTo","amount","nextAction","promiseOn","effectiveDate","evidence");}
    private String form(Model m,String kind){m.addAttribute("formKind",kind);return "credit/form";}
    private static String root(String feature){return "/finance/credit/"+feature;}
    private static void reject(BindingResult errors,IllegalArgumentException e){String key=key(e);String field=key.substring("credit.error.".length());if(field.equals("reference")&&errors.getTarget() instanceof AssessmentForm)field="policyReference";if(Set.of("income","expenses","otherDebt","capacity","assessedOn","validThrough","evidence","reference","policyReference","verified","code","description","owner","ownerEvidence","amount","encumbrance","effectiveDate","reason","nextAction","assignedTo","reminderDaysBefore","reminderEveryDays").contains(field))errors.rejectValue(field,key);else errors.reject(key);}
    private static String key(IllegalArgumentException e){var message=Objects.toString(e.getMessage(),"");return message.matches("credit\\.error\\.[A-Za-z]+")?message:"credit.error.invalid";}
    @GetMapping("/policy") public String policy(@AuthenticationPrincipal AppUserPrincipal a,Model m){var p=service.policy(a);var f=new PolicyForm();f.setExpectedRevision(p.revision());f.setCapacityRequired(p.capacityRequired());f.setCollateralRequired(p.collateralRequired());f.setReference(p.reference());f.setRemindersEnabled(p.remindersEnabled());f.setReminderDaysBefore(p.reminderDaysBefore());f.setReminderEveryDays(p.reminderEveryDays());m.addAttribute("policyForm",f);return form(m,"policy");}
    @PostMapping("/policy") public String policy(@AuthenticationPrincipal AppUserPrincipal a,@ModelAttribute("policyForm") PolicyForm f,BindingResult errors,Model m){service.authorize(a,"CREDIT_CONTROLS","CONFIGURE");if(!errors.hasErrors())try{service.configure(a,f);return "redirect:"+root("policy");}catch(IllegalArgumentException e){reject(errors,e);}return form(m,"policy");}
    @GetMapping("/guarantors") public String guarantees(@AuthenticationPrincipal AppUserPrincipal a,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="loan_asc") String sort,Model m){m.addAttribute("records",service.guarantees(a,search,page,sort));m.addAttribute("search",search);m.addAttribute("sort",sort);m.addAttribute("register","guarantors");return "credit/register";}
    @GetMapping("/guarantors/{id}") public String guarantee(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@RequestParam(defaultValue="0") int page,Model m){m.addAttribute("guarantee",service.guarantee(a,id));m.addAttribute("records",service.assessments(a,id,page));m.addAttribute("detail","guarantor");return "credit/details";}
    @GetMapping("/guarantors/{id}/assess") public String assess(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,Model m){service.authorize(a,"GUARANTOR_CAPACITY","CREATE");m.addAttribute("guarantee",service.guarantee(a,id));var f=new AssessmentForm();f.setAssessedOn(service.today());m.addAttribute("assessmentForm",f);return form(m,"assessment");}
    @PostMapping("/guarantors/{id}/assess") public String assess(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@ModelAttribute("assessmentForm") AssessmentForm f,BindingResult errors,Model m){service.authorize(a,"GUARANTOR_CAPACITY","CREATE");if(!errors.hasErrors())try{service.assess(a,id,f);return "redirect:"+root("guarantors/")+id;}catch(IllegalArgumentException e){reject(errors,e);}m.addAttribute("guarantee",service.guarantee(a,id));return form(m,"assessment");}
    @GetMapping("/collateral") public String assets(@AuthenticationPrincipal AppUserPrincipal a,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="code_asc") String sort,Model m){m.addAttribute("records",service.assets(a,search,page,sort));m.addAttribute("search",search);m.addAttribute("sort",sort);m.addAttribute("register","collateral");return "credit/register";}
    @GetMapping("/collateral/new") public String newAsset(@AuthenticationPrincipal AppUserPrincipal a,Model m){service.authorize(a,"COLLATERAL","CREATE");m.addAttribute("assetForm",new AssetForm());return form(m,"asset");}
    @PostMapping("/collateral/new") public String newAsset(@AuthenticationPrincipal AppUserPrincipal a,@ModelAttribute("assetForm") AssetForm f,BindingResult errors,Model m){service.authorize(a,"COLLATERAL","CREATE");if(!errors.hasErrors())try{return "redirect:"+root("collateral/")+service.createAsset(a,f);}catch(IllegalArgumentException e){reject(errors,e);}catch(org.springframework.dao.DuplicateKeyException e){errors.rejectValue("code","credit.error.duplicateCode");}return form(m,"asset");}
    @GetMapping("/collateral/{id}") public String asset(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="0") int pledgePage,Model m){m.addAttribute("asset",service.asset(a,id));m.addAttribute("records",service.collateralHistory(a,id,page));m.addAttribute("pledges",service.pledges(a,id,pledgePage));m.addAttribute("detail","collateral");return "credit/details";}
    private void collateralContext(AppUserPrincipal a,UUID id,CollateralForm f,Model m){m.addAttribute("asset",service.asset(a,id));if(f.getLoanId()!=null)m.addAttribute("loan",service.loan(a,"COLLATERAL",f.getLoanId()));}
    @GetMapping("/collateral/{id}/events/new") public String collateral(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@RequestParam(defaultValue="VALUATION") String kind,@RequestParam(required=false) UUID loanId,Model m){service.authorize(a,"COLLATERAL",Set.of("RELEASE","RECOVERY").contains(kind)?kind:"UPDATE");var asset=service.asset(a,id);var f=new CollateralForm();f.setExpectedSequence(asset.sequence());f.setKind(kind);f.setLoanId(loanId);f.setEffectiveDate(service.today());m.addAttribute("collateralForm",f);collateralContext(a,id,f,m);return form(m,"collateralEvent");}
    @PostMapping("/collateral/{id}/events/new") public String collateral(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@ModelAttribute("collateralForm") CollateralForm f,BindingResult errors,Model m){service.authorize(a,"COLLATERAL",Set.of("RELEASE","RECOVERY").contains(f.getKind())?f.getKind():"UPDATE");if(!errors.hasErrors())try{service.collateral(a,id,f);return "redirect:"+root("collateral/")+id;}catch(IllegalArgumentException e){reject(errors,e);}collateralContext(a,id,f,m);return form(m,"collateralEvent");}
    @GetMapping("/loans") public String loanChoices(@AuthenticationPrincipal AppUserPrincipal a,@RequestParam String feature,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,@RequestParam(required=false) UUID assetId,Model m){m.addAttribute("records",service.loans(a,feature,search,page,feature.equals("COLLECTIONS")));m.addAttribute("feature",feature);m.addAttribute("search",search);m.addAttribute("assetId",assetId);if(assetId!=null)service.asset(a,assetId);return "credit/loan-picker";}
    @GetMapping("/loans/{id}") public String loan(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@RequestParam String feature,Model m){m.addAttribute("loan",service.loan(a,feature,id));m.addAttribute("detail","loan");return "credit/details";}
    @GetMapping("/collections") public String cases(@AuthenticationPrincipal AppUserPrincipal a,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="next_asc") String sort,Model m){m.addAttribute("records",service.cases(a,search,page,sort));m.addAttribute("search",search);m.addAttribute("sort",sort);m.addAttribute("register","collections");return "credit/register";}
    @GetMapping("/collections/{id}") public String collection(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@RequestParam(defaultValue="0") int page,Model m){var c=service.collection(a,id);m.addAttribute("collectionCase",c);m.addAttribute("loan",service.loan(a,"COLLECTIONS",c.loanId()));m.addAttribute("records",service.collectionHistory(a,id,page));m.addAttribute("detail","collection");return "credit/details";}
    @GetMapping("/collections/new") public String createCase(@AuthenticationPrincipal AppUserPrincipal a,@RequestParam UUID loanId,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,Model m){service.authorize(a,"COLLECTIONS","CREATE");var f=new CaseForm();f.setLoanId(loanId);f.setNextAction(service.today());m.addAttribute("caseForm",f);m.addAttribute("loan",service.loan(a,"COLLECTIONS",loanId));m.addAttribute("officers",service.officers(a,search,page));m.addAttribute("search",search);return form(m,"case");}
    @PostMapping("/collections/new") public String createCase(@AuthenticationPrincipal AppUserPrincipal a,@ModelAttribute("caseForm") CaseForm f,BindingResult errors,Model m){service.authorize(a,"COLLECTIONS","CREATE");if(!errors.hasErrors())try{return "redirect:"+root("collections/")+service.createCase(a,f);}catch(IllegalArgumentException e){reject(errors,e);}if(f.getLoanId()!=null)m.addAttribute("loan",service.loan(a,"COLLECTIONS",f.getLoanId()));m.addAttribute("officers",service.officers(a,"",0));m.addAttribute("selectedOfficer",service.officerChoice(a,f.getAssignedTo()));return form(m,"case");}
    @GetMapping("/collections/{id}/events/new") public String followUp(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@RequestParam(defaultValue="CONTACT") String kind,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,Model m){service.authorize(a,"COLLECTIONS","UPDATE");var c=service.collection(a,id);var f=new CollectionForm();f.setExpectedSequence(c.sequence());f.setKind(kind);f.setEffectiveDate(service.today());f.setNextAction(service.today());m.addAttribute("collectionForm",f);m.addAttribute("collectionCase",c);m.addAttribute("officers",service.officers(a,search,page));m.addAttribute("search",search);return form(m,"followUp");}
    @PostMapping("/collections/{id}/events/new") public String followUp(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,@ModelAttribute("collectionForm") CollectionForm f,BindingResult errors,Model m){service.authorize(a,"COLLECTIONS","UPDATE");if(!errors.hasErrors())try{service.followUp(a,id,f);return "redirect:"+root("collections/")+id;}catch(IllegalArgumentException e){reject(errors,e);}m.addAttribute("collectionCase",service.collection(a,id));m.addAttribute("officers",service.officers(a,"",0));m.addAttribute("selectedOfficer",service.officerChoice(a,f.getAssignedTo()));return form(m,"followUp");}
    @ExceptionHandler(IllegalArgumentException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) public String invalid(IllegalArgumentException e,Model m){m.addAttribute("creditError",key(e));return "credit/error";}
}
